"""
API key validation middleware that emits auth failure metrics.
Place AFTER MetricsMiddleware so HTTP totals are still recorded.
"""

from fastapi import Request, Response
from starlette.middleware.base import BaseHTTPMiddleware

from metrics.registry import AUTH_FAILURES_TOTAL

_SERVICE      = "api-gateway"
_VALID_KEYS   = {"ibts-api-key-dev", "ibts-api-key-dev-2"}   # load from env/secrets in prod
_SKIP_AUTH    = frozenset({"/metrics", "/health"})


class AuthMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        if request.url.path in _SKIP_AUTH:
            return await call_next(request)

        api_key = request.headers.get("x-api-key", "").strip()

        if not api_key:
            AUTH_FAILURES_TOTAL.labels(
                service=_SERVICE, reason="missing_key"
            ).inc()
            return Response(
                content     = '{"detail":"API key required"}',
                status_code = 401,
                media_type  = "application/json",
            )

        if api_key not in _VALID_KEYS:
            AUTH_FAILURES_TOTAL.labels(
                service=_SERVICE, reason="invalid_key"
            ).inc()
            return Response(
                content     = '{"detail":"Invalid API key"}',
                status_code = 403,
                media_type  = "application/json",
            )

        return await call_next(request)

